def format_invocation(name='', args=(), kwargs=None, **kw):
    if kwargs is None:
        kwargs = {}
    repr_func = kw.pop('repr', repr)
    if kw:
        raise TypeError(f'unexpected keyword arguments: {sorted(kw.keys())}')

    args_strs = [repr_func(arg) for arg in args]
    kwargs_strs = [f'{k}={repr_func(v)}' for k, v in kwargs.items()]

    all_parts = args_strs + kwargs_strs
    return f"{name}({', '.join(all_parts)})"
