def _format_t(path, root=T):
    if not path:
        return repr(root)

    root_name = {T: 'T', S: 'S', A: 'A'}.get(root, 'T')
    parts = [root_name]

    i = 0
    while i < len(path):
        op, arg = path[i], path[i + 1]
        i += 2

        if op == '.':
            parts.append(f'.{arg}')
        elif op == '[':
            if isinstance(arg, slice):
                parts.append(f'[{_format_slice(arg)}]')
            else:
                parts.append(f'[{bbrepr(arg)}]')
        elif op == 'P':
            parts.append(f'[{bbrepr(arg)}]')
        elif op == '(':
            args, kwargs = arg
            args_strs = [bbrepr(a) for a in args]
            kwargs_strs = [f'{k}={bbrepr(v)}' for k, v in kwargs.items()]
            all_parts = args_strs + kwargs_strs
            parts.append(f'({", ".join(all_parts)})')
        elif op == 'x':
            parts.append('.__star__()')
        elif op == 'X':
            parts.append('.__starstar__()')
        elif op == '+':
            parts.append(f' + {bbrepr(arg)}')
        elif op == '-':
            parts.append(f' - {bbrepr(arg)}')
        elif op == '*':
            parts.append(f' * {bbrepr(arg)}')
        elif op == '/':
            parts.append(f' / {bbrepr(arg)}')
        elif op == '%':
            parts.append(f' % {bbrepr(arg)}')
        elif op == ':':
            parts.append(f' ** {bbrepr(arg)}')
        elif op == '&':
            parts.append(f' & {bbrepr(arg)}')
        elif op == '|':
            parts.append(f' | {bbrepr(arg)}')
        elif op == '^':
            parts.append(f' ^ {bbrepr(arg)}')
        elif op == '~':
            parts.append('~')
        elif op == '_':
            parts.append('-')

    result = ''.join(parts)
    if any(c in result for c in ' +-*/%&|^'):
        if result[0] in '~-':
            return result
        return f'({result})'
    return result
